  /** 创建三角形实体、规范其参数并按密度同步质量，加入世界后返回。 */ addTriangle(pos: Vec2, size: Vec2): TriangleEntity {
    const entity = new TriangleEntity(this.allocateId(), pos, size)
    normalizeEntity(entity)
