/** 加载音频元信息并要求有限非负时长，完成后释放媒体源和监听。 */ function audioMetadata(source:string):Promise<number>{
  return new Promise(/** 建立音频元信息读取器，使用一次性完成保护和超时拒绝。 */ (resolve,reject)=>{
