  const bindLocals = new Map<string, BoneWorld>(rig.bones.map(/** 结构说明（自动提取）：rig.bones.map 回调；输入 bone；返回表达式求值结果。 */ bone => [bone.id, { position: { ...bone.position }, rotation: bone.rotation, scale: { ...bone.scale } }] as [string, BoneWorld]))
